import {
  copyFile,
  mkdir,
  readdir,
  readFile,
  writeFile,
} from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const currentDir = path.dirname(fileURLToPath(import.meta.url));
const iconSvgDir = path.resolve(currentDir, '../src/icon/svg');
const distDir = path.resolve(currentDir, '../dist');
const assetsDir = path.join(distDir, 'assets/icons');

const header = variant =>
  [
    '/**',
    ` * Built-in icons as ${variant}.`,
    ' * Auto-generated by packages/vitals/tools/generate-icon-css.mjs. Do not edit manually.',
    ' * The icons already work without this file; load it to serve them differently, or copy a rule to override one icon.',
    ' */',
    '',
  ].join('\n');

const rule = (name, value) =>
  `mh-icon[name='${name}']::part(base) {\n  mask-image: ${value};\n}\n`;

const dataUri = svg => `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;

const names = (await readdir(iconSvgDir))
  .filter(file => file.endsWith('.svg'))
  .map(file => file.replace(/\.svg$/u, ''))
  .sort((a, b) => a.localeCompare(b));

await mkdir(assetsDir, { recursive: true });

const urlRules = [];
const inlineRules = [];

for (const name of names) {
  const file = `${name}.svg`;
  await copyFile(path.join(iconSvgDir, file), path.join(assetsDir, file));
  urlRules.push(rule(name, `url('./assets/icons/${file}')`));
  inlineRules.push(
    rule(name, dataUri(await readFile(path.join(iconSvgDir, file), 'utf8'))),
  );
}

await writeFile(
  path.join(distDir, 'icons-url.css'),
  `${header('files')}\n${urlRules.join('\n')}`,
);
await writeFile(
  path.join(distDir, 'icons-inline.css'),
  `${header('inlined data URIs')}\n${inlineRules.join('\n')}`,
);

console.log(
  `Generated icons-url.css and icons-inline.css for ${String(names.length)} icons`,
);
